use mbse_exchange::{project_sets::{self as p,*},v2};
use mbse_model::{stage1::*,local_input::rooted::Directory};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{path::{Path,PathBuf},collections::BTreeMap,io::{Cursor,Write}};
const NATIVE:&[u8]=include_bytes!("../../../docs/parity/p37b/verification/native-02/run/metrics-final-cold-copy.kernspan");
const VIEWS:&[u8]=include_bytes!("../../../docs/parity/p37b/verification/native-02/run/metrics-final-cold-copy.mbse-views.json");
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn area()->tempfile::TempDir{tempfile::tempdir_in(std::env::var_os("TMPDIR").unwrap()).unwrap()}
fn write(root:&Path,path:&str,bytes:&[u8])->FileSpec{let full=root.join(path);std::fs::create_dir_all(full.parent().unwrap()).unwrap();std::fs::write(full,bytes).unwrap();FileSpec{path:path.into(),sha256:hash(bytes)}}
fn native(root:&Path,key:&str,path:&str,bytes:&[u8])->MemberSpec{MemberSpec{key:key.into(),format:Format::NativeSaved,primary:write(root,path,bytes),companions:vec![]}}
fn descriptor(root:&Path,members:Vec<MemberSpec>)->PathBuf{let p=root.join("projects.json");std::fs::write(&p,serde_json::to_vec_pretty(&Manifest{profile:p::PROFILE.into(),schema_version:1,members}).unwrap()).unwrap();p}
fn open(path:&Path)->ProjectSet{ProjectSet::open(path).unwrap_or_else(|e|panic!("{e}"))}
fn xml(name:&str,href:&str)->Vec<u8>{format!(r##"<xmi:XMI xmlns:xmi="http://www.omg.org/spec/XMI/20131001" xmlns:uml="http://www.omg.org/spec/UML/20131001"><uml:Model xmi:id="model" name="M"><packagedElement xmi:type="uml:Class" xmi:id="dup" name="{name}"/>{href}</uml:Model></xmi:XMI>"##).into_bytes()}
#[test]
fn project_set_native_members_keep_duplicate_local_ids_raw_opaque_and_all_eight_maps_without_source_or_target_writes(){
 let a=area();let root=a.path();let mut left=native(root,"left","left/native.kernspan",NATIVE);left.companions.push(CompanionSpec{role:CompanionRole::NativeViews,file:write(root,"left/native.mbse-views.json",VIEWS)});let mut changed:Value=serde_json::from_slice(NATIVE).unwrap();changed["snapshot"]["records"]["1"]["name"]=json!("Right member retains its own native meaning");let bytes=serde_json::to_vec(&changed).unwrap();let right=native(root,"right","right/native.kernspan",&bytes);let path=descriptor(root,vec![left,right]);let original=std::fs::read(&path).unwrap();let set=open(&path);
 let left_key=set.keys("left").into_iter().find(|k|k.identity==LocalIdentity::NativeRecord(RecordId(1))).unwrap();let right_key=set.keys("right").into_iter().find(|k|k.identity==LocalIdentity::NativeRecord(RecordId(1))).unwrap();assert_ne!(left_key,right_key);assert_ne!(set.native_record(&left_key).unwrap().name,set.native_record(&right_key).unwrap().name);assert_eq!(set.native_snapshot("left").unwrap(),&serde_json::from_value::<Snapshot>(serde_json::from_slice::<Value>(NATIVE).unwrap()["snapshot"].clone()).unwrap());
 let doc=serde_json::to_value(set.bound_views("left",0).unwrap()).unwrap();let original_views:Value=serde_json::from_slice(VIEWS).unwrap();for map in["views","occurrences","edges","typed_ports","connector_edges","activity_diagrams","state_machine_diagrams","scenario_diagrams"]{assert_eq!(doc[map],original_views[map]);}assert!(set.recheck().unwrap().unchanged);assert_eq!(std::fs::read(root.join("left/native.kernspan")).unwrap(),NATIVE);assert_eq!(std::fs::read(root.join("right/native.kernspan")).unwrap(),bytes);assert_eq!(std::fs::read(&path).unwrap(),original);
 let replica=area();for rel in["left/native.kernspan","left/native.mbse-views.json","right/native.kernspan","projects.json"]{let target=replica.path().join(rel);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::copy(root.join(rel),target).unwrap();}let reopened=open(&replica.path().join("projects.json"));assert_eq!(reopened.summary().source_set_digest,set.summary().source_set_digest);assert_eq!(reopened.keys("left"),set.keys("left"));assert_eq!(reopened.native_snapshot("left"),set.native_snapshot("left"));
}
#[test]
fn project_set_identical_copied_native_projects_stay_distinct_by_member_even_when_document_hash_and_record_ids_match(){
 let a=area();let left=native(a.path(),"left","common.kernspan",NATIVE);let mut right=left.clone();right.key="right".into();let set=open(&descriptor(a.path(),vec![left,right]));let l=&set.keys("left")[0];let r=&set.keys("right")[0];assert_eq!(l.primary_sha256,r.primary_sha256);assert_eq!(l.identity,r.identity);assert_ne!(l,r);assert_eq!(set.native_snapshot("left").unwrap(),set.native_snapshot("right").unwrap());assert_eq!(set.keys("missing"),Vec::<ElementKey>::new());
}
#[test]
fn project_set_external_equal_original_ids_reuse_existing_v2_projection_but_never_merge_project_members(){
 let a=area();let source=write(a.path(),"same.xmi",&xml("Synthetic classifier",""));let members=["supplier","consumer"].into_iter().map(|key|MemberSpec{key:key.into(),format:Format::SemanticV2,primary:source.clone(),companions:vec![]}).collect();let set=open(&descriptor(a.path(),members));let find=|member|set.keys(member).into_iter().find(|k|matches!(&k.identity,LocalIdentity::External(e)if e.identity==v2::ElementIdentity::Original("dup".into()))).unwrap();let l=find("supplier");let r=find("consumer");assert_ne!(l,r);assert_eq!(l.identity,r.identity);assert_eq!(set.external_node(&l).unwrap().name,"Synthetic classifier");assert!(set.native_record(&l).is_none());assert!(set.semantic("supplier").unwrap().admission_preview(&[]).admitted==false);
}
#[test]
fn project_set_missing_changed_and_wrong_native_binding_companions_are_visible_without_rewriting_primary_or_claiming_admission(){
 let a=area();let mut member=native(a.path(),"main","native.kernspan",NATIVE);let mut changed=write(a.path(),"changed.json",b"changed companion");changed.sha256=hash(VIEWS);let mut wrong:Value=serde_json::from_slice(VIEWS).unwrap();wrong["binding"]["artifact_sha256"]=json!("a".repeat(64));member.companions=vec![CompanionSpec{role:CompanionRole::NativeViews,file:FileSpec{path:"missing.json".into(),sha256:hash(VIEWS)}},CompanionSpec{role:CompanionRole::NativeViews,file:changed},CompanionSpec{role:CompanionRole::NativeViews,file:write(a.path(),"wrong.json",&serde_json::to_vec(&wrong).unwrap())}];let set=open(&descriptor(a.path(),vec![member]));let m=&set.summary().members[0];assert_eq!(m.companions[0].file.state,FileState::Missing);assert_eq!(m.companions[1].file.state,FileState::Changed);assert_eq!(m.companions[2].file.state,FileState::Verified);assert!(m.companions[2].issue.as_ref().unwrap().contains("BINDING"));assert!(m.companions.iter().all(|c|!c.bound_declaration_checked));assert!(set.native_snapshot("main").is_some());assert!(set.bound_views("main",2).is_none());assert_eq!(std::fs::read(a.path().join("native.kernspan")).unwrap(),NATIVE);
}
#[test]
fn project_set_primary_change_retains_frozen_snapshot_and_old_keys_but_reopen_never_retargets_them_to_new_bytes(){
 let a=area();let member=native(a.path(),"main","native.kernspan",NATIVE);let path=descriptor(a.path(),vec![member.clone()]);let frozen=open(&path);let key=frozen.keys("main")[0].clone();let old=frozen.native_record(&key).unwrap().clone();let mut new:Value=serde_json::from_slice(NATIVE).unwrap();new["snapshot"]["records"][old.id.0.to_string()]["name"]=json!("Changed source same local ID");let bytes=serde_json::to_vec(&new).unwrap();std::fs::write(a.path().join("native.kernspan"),&bytes).unwrap();assert!(!frozen.recheck().unwrap().unchanged);assert_eq!(frozen.native_record(&key).unwrap(),&old);let mismatch=open(&path);assert_eq!(mismatch.summary().members[0].primary.state,FileState::Changed);assert!(mismatch.native_snapshot("main").is_none()&&mismatch.native_record(&key).is_none());let mut reviewed=member;reviewed.primary.sha256=hash(&bytes);descriptor(a.path(),vec![reviewed]);let accepted=open(&path);assert!(accepted.native_record(&key).is_none());assert_eq!(accepted.native_record(&accepted.keys("main")[0]).unwrap().name,"Changed source same local ID");
}
#[test]
fn project_set_recheck_never_parses_changed_manifest_or_follows_newly_proposed_files_and_old_report_remains_exact(){
 let a=area();let member=native(a.path(),"main","native.kernspan",NATIVE);let path=descriptor(a.path(),vec![member]);let frozen=open(&path);let old=serde_json::to_vec(&frozen.summary()).unwrap();std::fs::write(&path,br#"{"profile":"future","members":[{"primary":{"path":"https://invalid.example/never-fetch"}}]}"#).unwrap();let check=frozen.recheck().unwrap();assert!(!check.unchanged&&check.manifest.state==FileState::Changed);assert_eq!(check.files.len(),1);assert_eq!(check.files[0].1.state,FileState::Verified);assert_eq!(serde_json::to_vec(&frozen.summary()).unwrap(),old);assert!(ProjectSet::open(&path).is_err());
}
#[test]
fn project_set_offline_external_references_do_not_acquire_adjacent_or_uri_resources_even_when_opaque_companions_are_supplied(){
 let a=area();let unlisted=xml("Unlisted must not appear","");let neighbor=write(a.path(),"neighbor.uml",&unlisted);let bytes=xml("Only declared primary",r##"<packagedElement xmi:type="uml:Class" href="neighbor.uml#dup"/><packagedElement xmi:type="uml:Class" href="https://invalid.example/library.uml#remote"/>"##);let member=MemberSpec{key:"external".into(),format:Format::SemanticV2,primary:write(a.path(),"main.xmi",&bytes),companions:vec![CompanionSpec{role:CompanionRole::Opaque,file:neighbor}]};let set=open(&descriptor(a.path(),vec![member]));let projection=set.semantic("external").unwrap();assert_eq!(projection.assets.len(),1);assert!(projection.nodes.iter().all(|n|n.name!="Unlisted must not appear"));assert!(projection.references.iter().any(|r|r.resolution==v2::ReferenceResolution::UnsuppliedResource));assert_eq!(std::fs::read(a.path().join("neighbor.uml")).unwrap(),unlisted);assert!(set.recheck().unwrap().unchanged);
}
#[test]
fn project_set_saved_byte_inspection_rejects_recovery_future_duplicate_json_and_corrupt_primary_without_losing_captured_bytes(){
 let a=area();let original:Value=serde_json::from_slice(NATIVE).unwrap();for(name,mut v)in[("recovery",original.clone()),("future",original.clone())]{if name=="recovery"{v["kind"]=json!("recovery");}else{v["schema_version"]=json!(999);}let member=native(a.path(),name,&format!("{name}.kernspan"),&serde_json::to_vec(&v).unwrap());let set=open(&descriptor(a.path(),vec![member]));assert_eq!(set.summary().members[0].primary.state,FileState::Verified);assert!(set.summary().members[0].issue.is_some());assert!(set.native_snapshot(name).is_none());}
 let member=native(a.path(),"duplicate","duplicate.kernspan",br#"{"profile":"kernspan.stage1/2","profile":"future"}"#);let set=open(&descriptor(a.path(),vec![member]));assert!(set.summary().members[0].issue.as_ref().unwrap().contains("duplicate"));
}
#[test]
fn project_set_manifest_schema_keys_paths_hashes_roles_and_unknown_versions_refuse_without_touching_sources(){
 let a=area();let member=native(a.path(),"main","native.kernspan",NATIVE);let good=serde_json::to_value(Manifest{profile:p::PROFILE.into(),schema_version:1,members:vec![member]}).unwrap();let path=a.path().join("bad.json");let mut candidates=Vec::new();for raw in["../escape","/absolute","a//b","a/./b","a/../b","file:///native","https://invalid.example/x","a\\b"]{let mut v=good.clone();v["members"][0]["primary"]["path"]=json!(raw);candidates.push(v);}for change in["key","hash","role","version","unknown","duplicate-member"]{let mut v=good.clone();match change{"key"=>v["members"][0]["key"]=json!("bad/member"),"hash"=>v["members"][0]["primary"]["sha256"]=json!("A".repeat(64)),"role"=>{v["members"][0]["format"]=json!("SemanticV2");v["members"][0]["companions"]=json!([{"role":"NativeViews","file":{"path":"view.json","sha256":"a".repeat(64)}}]);},"version"=>v["schema_version"]=json!(99),"unknown"=>v["ambient_fetch"]=json!(true),_=>v["members"]=json!([v["members"][0].clone(),v["members"][0].clone()])};candidates.push(v);}
 for v in candidates{let bytes=serde_json::to_vec(&v).unwrap();std::fs::write(&path,&bytes).unwrap();assert!(ProjectSet::open(&path).is_err());assert_eq!(std::fs::read(&path).unwrap(),bytes);}std::fs::write(&path,br#"{"profile":"x","profile":"y","schema_version":1,"members":[]}"#).unwrap();assert!(ProjectSet::open(&path).err().unwrap().contains("duplicate"));assert_eq!(std::fs::read(a.path().join("native.kernspan")).unwrap(),NATIVE);
}
#[test]
fn project_set_member_artifact_and_manifest_boundaries_are_exact_and_do_not_silently_truncate(){
 let a=area();let one=native(a.path(),"one","native.kernspan",NATIVE);let members=(0..16).map(|i|{let mut m=one.clone();m.key=format!("member{i}");m}).collect();let path=descriptor(a.path(),members);assert_eq!(open(&path).summary().members.len(),16);let mut m:Manifest=serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();let mut extra=one.clone();extra.key="extra".into();m.members.push(extra);std::fs::write(&path,serde_json::to_vec(&m).unwrap()).unwrap();assert!(ProjectSet::open(&path).err().unwrap().contains("MEMBER_LIMIT"));
 let mut m=one;for i in 0..63{m.companions.push(CompanionSpec{role:CompanionRole::Opaque,file:write(a.path(),&format!("file{i}"),b"")});}let path=descriptor(a.path(),vec![m.clone()]);assert_eq!(open(&path).summary().members[0].companions.len(),63);m.companions.push(CompanionSpec{role:CompanionRole::Opaque,file:write(a.path(),"extra",b"")});let path=descriptor(a.path(),vec![m]);assert!(ProjectSet::open(&path).err().unwrap().contains("ARTIFACT_LIMIT"));let one=native(a.path(),"one","native.kernspan",NATIVE);let path=descriptor(a.path(),vec![one]);let mut bytes=std::fs::read(&path).unwrap();bytes.resize(p::MAX_MANIFEST_BYTES,b' ');std::fs::write(&path,&bytes).unwrap();assert!(ProjectSet::open(&path).is_ok());bytes.push(b' ');std::fs::write(&path,&bytes).unwrap();assert!(ProjectSet::open(&path).is_err());
}
#[test]
fn project_set_captured_input_budget_refuses_before_over_limit_file_allocation_and_preserves_files(){
 let a=area();let mut one=native(a.path(),"one","native.kernspan",NATIVE);for i in 0..4{let path=format!("sparse{i}");let full=a.path().join(&path);std::fs::File::create(&full).unwrap().set_len(16*1024*1024).unwrap();one.companions.push(CompanionSpec{role:CompanionRole::Opaque,file:FileSpec{path,sha256:"a".repeat(64)}});}let path=descriptor(a.path(),vec![one]);assert!(ProjectSet::open(&path).err().unwrap().contains("INPUT_BYTE_BUDGET"));assert_eq!(std::fs::metadata(a.path().join("sparse3")).unwrap().len(),16*1024*1024);
}
#[test]
fn project_set_aggregate_expanded_archive_budget_applies_across_existing_bounded_v2_member_adapters(){
 let a=area();let mut payload=vec![0u8;15*1024*1024];let mut seed=123456789u64;for chunk in payload.chunks_mut(4096){for b in chunk.iter_mut().take(1024){seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;*b=seed as u8;}}
 let mut zip=zip::ZipWriter::new(Cursor::new(Vec::new()));let options=zip::write::FileOptions::default().compression_method(zip::CompressionMethod::Deflated);zip.start_file("com.nomagic.magicdraw.uml_model.model",options).unwrap();zip.write_all(&xml("Bounded core","")).unwrap();for i in 0..3{zip.start_file(format!("opaque{i}"),options).unwrap();zip.write_all(&payload).unwrap();}let bytes=zip.finish().unwrap().into_inner();assert!(bytes.len()<v2::MAX_PRIMARY);let source=write(a.path(),"project.mdzip",&bytes);let members=["one","two"].into_iter().map(|key|MemberSpec{key:key.into(),format:Format::SemanticV2,primary:source.clone(),companions:vec![]}).collect();let path=descriptor(a.path(),members);assert!(ProjectSet::open(&path).err().unwrap().contains("EXPANDED_BYTE_BUDGET"));assert_eq!(std::fs::metadata(a.path().join("project.mdzip")).unwrap().len(),bytes.len()as u64);
}
#[test]
fn project_set_aggregate_element_budget_counts_native_record_identities_across_members_without_global_id_deduplication(){
 let a=area();let mut snapshot=Snapshot::new(DocumentId("bounded-large-native".into()));snapshot.records=BTreeMap::new();for id in 1..=65536{snapshot.records.insert(RecordId(id),Record{id:RecordId(id),kind:RecordKind::System,name:"n".into(),scope:RecordId(id),fields:BTreeMap::new()});}snapshot.next_id=65537;let mut envelope:Value=serde_json::from_slice(NATIVE).unwrap();envelope["snapshot"]=serde_json::to_value(snapshot).unwrap();let bytes=serde_json::to_vec(&envelope).unwrap();assert!(bytes.len()<mbse_model::stage1_io::MAX_BYTES);let source=write(a.path(),"large.kernspan",&bytes);let members=["left","right"].into_iter().map(|key|MemberSpec{key:key.into(),format:Format::NativeSaved,primary:source.clone(),companions:vec![]}).collect();let path=descriptor(a.path(),members);assert!(ProjectSet::open(&path).err().unwrap().contains("ELEMENT_BUDGET"));
}
#[cfg(unix)]
#[test]
fn project_set_rooted_reader_refuses_leaf_and_ancestor_symlinks_and_retains_old_directory_capability_after_path_swap(){
 use std::os::unix::fs::symlink;let a=area();let root=a.path().join("source");let outside=a.path().join("outside");std::fs::create_dir_all(&root).unwrap();std::fs::create_dir_all(&outside).unwrap();write(&outside,"native.kernspan",NATIVE);symlink(&outside,root.join("linked")).unwrap();let member=MemberSpec{key:"linked".into(),format:Format::NativeSaved,primary:FileSpec{path:"linked/native.kernspan".into(),sha256:hash(NATIVE)},companions:vec![]};let path=descriptor(&root,vec![member]);let set=open(&path);assert!(matches!(set.summary().members[0].primary.state,FileState::Unavailable(_)));assert!(set.native_snapshot("linked").is_none());symlink(&path,root.join("manifest-link.json")).unwrap();assert!(ProjectSet::open(&root.join("manifest-link.json")).is_err());write(&root,"retained",b"old root bytes");write(&outside,"retained",b"outside must not be followed");let directory=Directory::open(&root).unwrap();std::fs::rename(&root,a.path().join("moved")).unwrap();symlink(&outside,&root).unwrap();assert_eq!(directory.read("retained",1024,"TEST").unwrap(),b"old root bytes");assert!(Directory::open(&root).is_err());assert!(set.recheck().is_err());
}
